# Stop-Stage4.ps1
# Teardown Stage 4 microservices stack
Write-Host "Stopping Stage 4 microservices stack..."
if (Test-Path "stage4-pids.json") {
    $Pids = Get-Content -Raw -Path "stage4-pids.json" | ConvertFrom-Json
    foreach ($ProcName in $Pids.psobject.Properties.Name) {
        $PidVal = $Pids.$ProcName
        if ($PidVal) {
            Write-Host "Stopping $ProcName (PID: $PidVal)..."
            Stop-Process -Id $PidVal -Force -ErrorAction SilentlyContinue
        }
    }
    Remove-Item "stage4-pids.json" -ErrorAction SilentlyContinue
} else {
    Write-Host "No stage4-pids.json file found. Cleaning up python/node processes on Stage 4 ports..."
    # Fallback: find and kill processes on ports 18000, 18001, 18002, 18003, 18100
    $Ports = @(18000, 18001, 18002, 18003, 18100)
    foreach ($Port in $Ports) {
        $Netstat = netstat -ano | Select-String "LISTENING" | Select-String ":$Port "
        if ($Netstat) {
            $NetstatLine = $Netstat[0].ToString()
            $Tokens = $NetstatLine -split '\s+' | Where-Object { $_ }
            $PidVal = $Tokens[-1]
            if ($PidVal -as [int]) {
                Write-Host "Killing process listening on port $Port (PID: $PidVal)..."
                Stop-Process -Id [int]$PidVal -Force -ErrorAction SilentlyContinue
            }
        }
    }
}
Write-Host "Teardown complete."

